              *d++ = c;
              s += 2;
            }
        }
      else
        *d++ = *s;
    }
  *d = '\0';

  len = d - decoded;

  if (!(flags & G_URI_FLAGS_ENCODED) &&
      !g_utf8_validate (decoded, len, &invalid))
